/**
 * Calendar arithmetic for recurring-issue rules.
 *
 * A rule's dates are `YYYY-MM-DD` strings with no time of day; the only clock
 * involved is the instant the job runs at, read in the rule's own time zone.
 * Pure functions only, so the schema (client and server) and the job share one
 * definition of "a real date" and "the latest started occurrence".
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True when `timeZone` is an IANA name the runtime's `Intl` knows. */
export function isValidTimeZone(timeZone: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
    return true;
  } catch {
    return false;
  }
}

/** True for a `YYYY-MM-DD` string that names a real calendar day. */
export function isCalendarDate(value: string): boolean {
  const match = DATE_PATTERN.exec(value);
  if (match === null) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = utcMidnight(year, month, day);

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** The calendar date `instant` falls on in `timeZone`, as `YYYY-MM-DD`. */
export function localDateIn(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  const part = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((candidate) => candidate.type === type)?.value ?? "";

  return `${part("year")}-${part("month")}-${part("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` date: 1 = Monday … 7 = Sunday. */
export function isoWeekdayOf(date: string): number {
  const day = utcDateOf(date).getUTCDay();
  return day === 0 ? 7 : day;
}

/** `date` moved by `days` calendar days (negative goes back). */
export function shiftDate(date: string, days: number): string {
  const shifted = utcDateOf(date);
  shifted.setUTCDate(shifted.getUTCDate() + days);
  return shifted.toISOString().slice(0, 10);
}

/**
 * The latest occurrence whose day has started by `now`, or `null` when none
 * has started yet. A day has started once its 00:00 has passed in the rule's
 * time zone, which is exactly when the local calendar date reaches it.
 */
export function latestStartedOccurrence(
  rule: {
    readonly cadence: RecurrenceCadence;
    readonly weekday: number | null;
    readonly startsOn: string;
    readonly timezone: string;
  },
  now: Date,
): string | null {
  const today = localDateIn(now, rule.timezone);
  if (today < rule.startsOn) return null;
  if (rule.cadence === "daily") return today;
  if (rule.weekday === null) return null;

  // Step back to the most recent day with the rule's ISO weekday (today included).
  const sinceWeekday = (isoWeekdayOf(today) - rule.weekday + 7) % 7;
  const occurrence = shiftDate(today, -sinceWeekday);
  return occurrence < rule.startsOn ? null : occurrence;
}

function utcMidnight(year: number, month: number, day: number): Date {
  // `Date.UTC` maps years 0–99 onto 1900–1999; `setUTCFullYear` does not.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return date;
}

function utcDateOf(date: string): Date {
  const match = DATE_PATTERN.exec(date);
  if (match === null) throw new RangeError(`Malformed calendar date: "${date}"`);
  return utcMidnight(Number(match[1]), Number(match[2]), Number(match[3]));
}

