import { z } from "zod";
import { isCalendarDate, isValidTimeZone } from "@/lib/recurrence";
import {
  orgIdSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";
import { issuePrioritySchema } from "./issue";

/**
 * A recurring-issue rule as submitted. Cross-field rules live in the
 * `superRefine`: a weekly rule needs a weekday, a daily rule must not have one.
 */
export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the recurring issue a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z.string().refine(isValidTimeZone, "must be an IANA time zone"),
    startsOn: z
      .string()
      .refine(isCalendarDate, "must be a real YYYY-MM-DD calendar date"),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a weekly rule needs a weekday",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "a daily rule has no weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;

