input.content:
/**
 * Recurring-issue rule rows: tenant-scoped reads and writes for the service
 * layer, plus the cross-tenant sweep the job runs.
 *
 * `countRecurringIssues` and `insertRecurringIssue` are deliberately
 * synchronous. The plan-cap check and the insert happen back to back in the
 * service with no `await` between them, so two concurrent requests cannot both
 * pass the cap.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";

/** Creation order, with the rowid breaking ties between same-millisecond rows. */
const CREATION_ORDER = [asc(recurringIssues.createdAt), sql`rowid`] as const;

export function countRecurringIssues(orgId: OrgId): number {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export function insertRecurringIssue(rule: RecurringIssue): RecurringIssue {
  const row = getDb()
    .insert(recurringIssues)
    .values(rule)
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(...CREATION_ORDER)
    .all();
  return rows.map(toRecurringIssue);
}

/** Every non-paused rule across all organizations, for the job's sweep. */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(...CREATION_ORDER)
    .all();
  return rows.map(toRecurringIssue);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

/** Records the occurrence day an issue was successfully filed for. */
export async function recordOccurrence(
  orgId: OrgId,
  recurringIssueId: string,
  occurrenceOn: string,
): Promise<void> {
  getDb()
    .update(recurringIssues)
    .set({
      lastOccurrenceOn: occurrenceOn,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .run();
}

