/**
 * Files the issue each due recurring-issue rule owes, at most one per rule per run.
 *
 * Must call (do not reimplement): can, latestStartedOccurrence, createIssue, resolveActor
 */
import { can } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import { latestStartedOccurrence } from "@/lib/recurrence";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { resolveActor } from "@/server/services/member-service";
import type { RecurringIssue } from "@/types/recurring-issue";
import { runJob } from "./types";
import type { JobResult } from "./types";

const logger = createLogger("recurring-issue-job");

/** What happened to one rule on this run. */
type Outcome = "filed" | "skipped" | "paused";

/**
 * Walks every non-paused rule. Missed occurrences are never back-filled: the
 * issue is always for the latest started occurrence L, and only if L is later
 * than the last one filed. A failing rule is counted and the sweep moves on.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const outcome = await fileDueOccurrence(rule, now);
        if (outcome === "filed") result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue was not filed", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function fileDueOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<Outcome> {
  const occurrence = latestStartedOccurrence(rule, now);
  if (occurrence === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  // An archived project keeps the rule as it is; the next run after a restore
  // files the then-latest occurrence.
  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    throw new Error(`Project ${rule.projectId} was not found`);
  }
  if (isArchived(project)) return "skipped";

  // The issue is filed as its creator. If they have left, or their role no
  // longer allows creating issues here, the rule pauses instead of retrying.
  const creator = await resolveActor(rule.createdBy, rule.orgId);
  if (creator === null || !can(creator, "issue:create", projectResource(project))) {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return "paused";
  }

  const assignee =
    rule.assigneeId === null
      ? null
      : await memberRepo.findMember(rule.orgId, rule.assigneeId);
  const assigneeId =
    assignee?.status === "active" ? assignee.userId : null;

  await createIssue(creator, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringRepo.recordOccurrence(rule.orgId, rule.id, occurrence);
  return "filed";
}

