describe("latestStartedOccurrence", () => {
  it("uses the local calendar date of the rule's zone", () => {
    const rule = { cadence: "daily" as const, weekday: null, startsOn: "2026-03-01", timezone: "America/New_York" };
    // 2026-03-05T03:00Z is 2026-03-04 22:00 in New York.
    expect(latestStartedOccurrence(rule, new Date("2026-03-05T03:00:00Z"))).toBe("2026-03-04");
  });

  it("does not count a day before its local 00:00 across a DST change", () => {
    const rule = { cadence: "daily" as const, weekday: null, startsOn: "2026-03-01", timezone: "America/New_York" };
    // 2026-03-08 00:00 EST is 05:00Z; at 04:30Z the day has not started yet.
    expect(latestStartedOccurrence(rule, new Date("2026-03-08T04:30:00Z"))).toBe("2026-03-07");
    expect(latestStartedOccurrence(rule, new Date("2026-03-08T05:00:00Z"))).toBe("2026-03-08");
  });

  it("finds the latest matching weekday and respects startsOn", () => {
    const thursday = { cadence: "weekly" as const, weekday: 4, startsOn: "2026-03-01", timezone: "UTC" };
    expect(latestStartedOccurrence(thursday, new Date("2026-03-05T12:00:00Z"))).toBe("2026-03-05");
    expect(latestStartedOccurrence(thursday, new Date("2026-03-09T12:00:00Z"))).toBe("2026-03-05");
    const late = { ...thursday, startsOn: "2026-03-06" };
    expect(latestStartedOccurrence(late, new Date("2026-03-09T12:00:00Z"))).toBeNull();
  });
});

describe("create, file, pause", () => {
  it("files one issue per run for the latest occurrence and never back-fills", async () => {
    const owner = tenant.actors.owner;
    const rule = await recurringService.createRecurringIssue(owner, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      title: "Daily triage",
      priority: "high",
      assigneeId: tenant.userIds.member,
      cadence: "daily",
      weekday: null,
      timezone: "UTC",
      startsOn: "2026-06-01",
    });
    expect(rule.lastOccurrenceOn).toBeNull();
    expect(rule.paused).toBe(false);

    const first = await runRecurringIssueJob(new Date("2026-06-03T07:00:00Z"));
    expect(first.processed).toBe(1);
    const again = await runRecurringIssueJob(new Date("2026-06-03T07:00:00Z"));
    expect(again.processed).toBe(0);
    const later = await runRecurringIssueJob(new Date("2026-06-07T07:00:00Z"));
    expect(later.processed).toBe(1);

    const page = await issueRepo.listIssues({ orgId: tenant.org.id, projectId: tenant.project.id, limit: 50 });
    const titles = page.items.map((issue) => issue.title).sort();
    expect(titles).toEqual(["Daily triage (2026-06-03)", "Daily triage (2026-06-07)"]);
    const filed = page.items.find((issue) => issue.title.endsWith("(2026-06-07)"));
    expect(filed?.status).toBe("backlog");
    expect(filed?.priority).toBe("high");
    expect(filed?.assigneeId).toBe(tenant.userIds.member);

    const rules = await recurringService.listRecurringIssues(owner, tenant.org.id);
    expect(rules[0]?.lastOccurrenceOn).toBe("2026-06-07");

    await recurringService.setRecurringIssuePaused(owner, {
      orgId: tenant.org.id,
      recurringIssueId: rule.id,
      paused: true,
    });
    const paused = await runRecurringIssueJob(new Date("2026-06-20T07:00:00Z"));
    expect(paused.processed).toBe(0);
  });

  it("refuses a rule on a plan with zero quota and stores nothing", async () => {
    await expect(
      recurringService.createRecurringIssue(free.actors.owner, {
        orgId: free.org.id,
        projectId: free.project.id,
        title: "Monday planning",
        priority: "none",
        assigneeId: null,
        cadence: "weekly",
        weekday: 1,
        timezone: "UTC",
        startsOn: "2026-06-01",
      }),
    ).rejects.toThrow();
    expect(await recurringService.listRecurringIssues(free.actors.owner, free.org.id)).toHaveLength(0);
  });
});
